import "server-only";
import type { AppLocale } from "@/i18n/locales";
import { toDecimalString } from "@/lib/money";
import type { DisplayStatus } from "@/lib/status";
import enStatus from "@/messages/en/Status.json";
import zhStatus from "@/messages/zh-TW/Status.json";
import { listQuotesForExport, type QuoteListItem, type QuoteListParams } from "@/services/quotes";

// CSV export of the quotes list (spec §1): UTF-8 BOM so Excel detects the
// encoding, RFC 4180 quoting with CRLF, and CSV-injection guarding.

/** Generated by us (dates, amounts): written as-is, never prefixed. */
export type TrustedCell = { trusted: string };
export type CsvCell = string | number | null | undefined | TrustedCell;

const BOM = "﻿";
// Spreadsheet apps evaluate cells starting with these as formulas (OWASP).
const FORMULA_START = /^[=+\-@\t\r]/;

export function csvEscape(cell: CsvCell): string {
  let text: string;
  if (cell == null) text = "";
  else if (typeof cell === "object") text = cell.trusted;
  else if (typeof cell === "number") text = Number.isFinite(cell) ? String(cell) : "";
  else text = FORMULA_START.test(cell) ? `'${cell}` : cell;
  return /[",\r\n]/.test(text) ? `"${text.replace(/"/g, '""')}"` : text;
}

/** RFC 4180: CRLF between records, UTF-8 BOM up front. */
export function toCsv(rows: CsvCell[][]): string {
  return BOM + rows.map((row) => row.map(csvEscape).join(",")).join("\r\n") + "\r\n";
}

/** quotes-YYYYMMDD.csv */
export function exportFilename(today: string): string {
  return `quotes-${today.replace(/-/g, "")}.csv`;
}

const COLUMNS = [
  "quotationNumber",
  "title",
  "status",
  "issuedDate",
  "validUntil",
  "companyName",
  "contactPerson",
  "email",
  "phone",
  "vatNumber",
  "salesperson",
  "currency",
  "subtotal",
  "discount",
  "tax",
  "otherFees",
  "total",
  "paymentTerms",
  "deliveryMethod",
  "deliveryDate",
] as const;
type Column = (typeof COLUMNS)[number];

// TODO(wave B): move to an "Export" messages namespace.
const HEADERS: Record<AppLocale, Record<Column, string>> = {
  en: {
    quotationNumber: "Quote number",
    title: "Title",
    status: "Status",
    issuedDate: "Issued date",
    validUntil: "Valid until",
    companyName: "Customer",
    contactPerson: "Contact person",
    email: "Email",
    phone: "Phone",
    vatNumber: "VAT number",
    salesperson: "Salesperson",
    currency: "Currency",
    subtotal: "Subtotal",
    discount: "Discount",
    tax: "Tax",
    otherFees: "Other fees",
    total: "Total",
    paymentTerms: "Payment terms",
    deliveryMethod: "Delivery",
    deliveryDate: "Delivery date",
  },
  "zh-TW": {
    quotationNumber: "報價單號",
    title: "主旨",
    status: "狀態",
    issuedDate: "報價日期",
    validUntil: "有效期限",
    companyName: "客戶名稱",
    contactPerson: "聯絡人",
    email: "電子郵件",
    phone: "電話",
    vatNumber: "統一編號",
    salesperson: "業務人員",
    currency: "幣別",
    subtotal: "小計",
    discount: "折扣",
    tax: "稅額",
    otherFees: "其他費用",
    total: "總計",
    paymentTerms: "付款條件",
    deliveryMethod: "交貨方式",
    deliveryDate: "交貨日期",
  },
};

const STATUS_LABELS: Record<AppLocale, Record<DisplayStatus, string>> = {
  en: enStatus,
  "zh-TW": zhStatus,
};

export type QuotesCsvOptions = {
  locale: AppLocale;
  currency: string;
  fractionDigits: number;
};

export function quotesToCsv(rows: QuoteListItem[], options: QuotesCsvOptions): string {
  const headers = HEADERS[options.locale] ?? HEADERS.en;
  const statusLabels = STATUS_LABELS[options.locale] ?? STATUS_LABELS.en;
  const money = (cents: number | null | undefined): TrustedCell => ({
    trusted: toDecimalString(cents ?? 0, options.fractionDigits),
  });
  const date = (value: string | null | undefined): TrustedCell => ({
    trusted: value ? value.slice(0, 10) : "",
  });

  const records: CsvCell[][] = rows.map((q) => {
    const cells: Record<Column, CsvCell> = {
      quotationNumber: q.quotationNumber,
      title: q.title,
      status: { trusted: statusLabels[q.displayStatus] },
      issuedDate: date(q.issuedDate),
      validUntil: date(q.validUntil),
      companyName: q.customer?.companyName,
      contactPerson: q.customer?.contactPerson,
      email: q.customer?.email,
      phone: q.customer?.phone,
      vatNumber: q.customer?.vatNumber,
      salesperson: q.salesperson,
      currency: { trusted: options.currency },
      subtotal: money(q.subtotal),
      discount: money(q.discountAmount),
      tax: money(q.taxAmount),
      otherFees: money(q.otherFees),
      total: money(q.totalAmount),
      paymentTerms: q.paymentMethod,
      deliveryMethod: q.shippingMethod,
      deliveryDate: date(q.shippingDate),
    };
    return COLUMNS.map((column) => cells[column]);
  });

  return toCsv([COLUMNS.map((column) => headers[column]), ...records]);
}

/** The quotes matching the list filters as a CSV document. */
export async function buildQuotesCsv(
  params: QuoteListParams,
  options: QuotesCsvOptions
): Promise<string> {
  return quotesToCsv(await listQuotesForExport(params), options);
}
